+    const index_t nDofs = m_dofMapperGlobal.freeSize();
+    gsMatrix<index_t> dofs(nDofs,2);   // Has information (patch, localIndex) for each global dof
+    dofs.setZero();
+
+    for (index_t k=0; k<nPatches; ++k)
