+                const index_t globalIndex = m_dofMapperGlobal.index(i,k);
+                GISMO_ASSERT( dofs(globalIndex,0) == 0, "Internal error.");
+                dofs(globalIndex,0) = k;
+                dofs(globalIndex,1) = m_dofMapperLocal[k].index(i,0);
