+                    SparseVector newConstr( m_dofMapperLocal[otherPatch].freeSize() );
+                    for (typename SparseVector::InnerIterator it(constr); it; ++it)
+                    {
+                        const index_t idx = m_dofMapperLocal[otherPatch].index( indexRef[it.row()] - 1, 0 );
